class ShopifyClientError extends Error {
  constructor(message, details = {}) {
    super(message);
    this.name = 'ShopifyClientError';
    this.code = details.code || 'SHOPIFY_CLIENT_ERROR';
    this.cause = details.cause;
    this.details = details.details || {};
  }
}

class ShopifyHttpError extends ShopifyClientError {
  constructor(message, details = {}) {
    super(message, {
      ...details,
      code: details.code || 'SHOPIFY_HTTP_ERROR'
    });
    this.name = 'ShopifyHttpError';
    this.status = details.status;
    this.statusText = details.statusText;
    this.url = details.url;
  }
}

class ShopifyGraphQLError extends ShopifyClientError {
  constructor(message, details = {}) {
    super(message, {
      ...details,
      code: details.code || 'SHOPIFY_GRAPHQL_ERROR'
    });
    this.name = 'ShopifyGraphQLError';
    this.errors = details.errors || [];
  }
}

function normalizeClientError(error, fallbackMessage, details = {}) {
  if (error instanceof ShopifyClientError) {
    return error;
  }

  return new ShopifyClientError(fallbackMessage || error.message, {
    ...details,
    cause: error,
    details: {
      ...(details.details || {}),
      originalMessage: error.message
    }
  });
}

module.exports = {
  ShopifyClientError,
  ShopifyHttpError,
  ShopifyGraphQLError,
  normalizeClientError
};
